parameters.json:
[
  {
    "key": "hintStart",
    "en": "Hello! Someone on the island is waiting. Press Teach and show {b} what to do.",
    "fr": "Coucou ! Quelqu’un t’attend sur l’île. Appuie sur Apprendre et montre à {b} quoi faire."
  },
  {
    "key": "hintEmpty",
    "en": "Drive {b} yourself first: press Teach and use the arrows. {b} remembers every step.",
    "fr": "Conduis {b} toi-même d’abord : appuie sur Apprendre et utilise les flèches. {b} retient chaque pas."
  },
  {
    "key": "hintPattern",
    "en": "Look at the steps: the same little dance, over and over. What if {b} could \"do this {n} times\"?",
    "fr": "Regarde les pas : la même petite danse, encore et encore. Et si {b} pouvait « faire ça {n} fois » ?"
  },
  {
    "key": "hintMissed",
    "en": "{b} did {w} of {t}. Which one did {b} walk past?",
    "fr": "{b} en a fait {w} sur {t}. Lequel a-t-il raté ?"
  },
  {
    "key": "hintBump",
    "en": "{b} bumped into something. Which step sent {b} the wrong way?",
    "fr": "{b} s’est cogné. Quel pas l’a envoyé du mauvais côté ?"
  },
  {
    "key": "hintWet",
    "en": "A puddle! {b} watered where there is no tulip. Where was {b} facing?",
    "fr": "Une flaque ! {b} a arrosé là où il n’y a pas de tulipe. Il regardait où ?"
  },
  {
    "key": "hintDone",
    "en": "Perfect! Could you do it with fewer blocks? A repeat counts as one.",
    "fr": "Parfait ! Tu peux le faire avec moins de blocs ? Un « répéter » compte pour un."
  },
  {
    "key": "hintDoneMany",
    "en": "It works, with {k} blocks. The same steps come back: a repeat could hold them.",
    "fr": "Ça marche, avec {k} blocs. Les mêmes pas reviennent : un « répéter » pourrait les tenir."
  },
  {
    "key": "hintPredictMiss",
    "en": "You tapped one tile, {b} stopped on another. Follow the steps with your finger, one by one.",
    "fr": "Tu as touché une case, {b} s’est arrêté sur une autre. Suis les pas avec ton doigt, un par un."
  },
  {
    "key": "oliveThinking",
    "en": "Olive is thinking…",
    "fr": "Olive réfléchit…"
  },
  {
    "key": "oliveResting",
    "en": "Olive is resting. Here is her written line.",
    "fr": "Olive se repose. Voici sa phrase écrite."
  },
  {
    "key": "oliveRung1",
    "en": "Run it twice: Olive never says a thank-you the same way.",
    "fr": "Lance-le deux fois : Olive ne dit jamais un merci de la même façon."
  },
  {
    "key": "oliveRung2",
    "en": "Turn the dial: \"same every time\" or \"surprise me\". Olive changes her mind.",
    "fr": "Tourne la molette : « pareil à chaque fois » ou « surprends-moi ». Olive change d’avis."
  },
  {
    "key": "oliveRung3",
    "en": "Olive turned the words into blocks. Place them and see if {b} agrees.",
    "fr": "Olive a transformé les mots en blocs. Pose-les et vois si {b} est d’accord."
  },
  {
    "key": "oliveRung4",
    "en": "Olive gave one step for \"three squares\". Olive cannot count: a repeat can.",
    "fr": "Olive a donné un seul pas pour « trois cases ». Olive ne sait pas compter : un « répéter », si."
  },
  {
    "key": "oliveRung5",
    "en": "Olive picked what Biscuit wants. Use \"if Olive says…\" to send {b} the right way.",
    "fr": "Olive a trouvé ce que veut Biscuit. Utilise « si Olive dit… » pour envoyer {b} du bon côté."
  },
  {
    "key": "oliveRung6",
    "en": "Olive was wrong about the thing ahead. Ask three times and count the yeses.",
    "fr": "Olive s’est trompée sur ce qu’il y a devant. Demande trois fois et compte les oui."
  },
  {
    "key": "oliveRung7",
    "en": "Olive guessed a number. A count block does not guess.",
    "fr": "Olive a deviné un nombre. Un bloc « compter » ne devine pas."
  },
  {
    "key": "oliveRung8",
    "en": "Olive got the small sum right and the big one wrong. A rule beats a guess.",
    "fr": "Olive a trouvé la petite somme, pas la grande. Une règle bat une devinette."
  },
  {
    "key": "oliveRung9",
    "en": "Olive ignored \"under 5 words\". The shape card kept the rule for her.",
    "fr": "Olive a ignoré « moins de 5 mots ». La carte de forme a gardé la règle à sa place."
  },
  {
    "key": "oliveRung10",
    "en": "Olive answered with confidence. Check it in a book before you believe it.",
    "fr": "Olive a répondu avec assurance. Vérifie dans un livre avant de la croire."
  },
  {
    "key": "oliveRung11",
    "en": "Olive translates one way better than the other. Tools have a good direction.",
    "fr": "Olive traduit mieux dans un sens que dans l’autre. Les outils ont un bon sens."
  },
  {
    "key": "oliveRung12",
    "en": "A poem for the tulip. Sometimes silly, always hers.",
    "fr": "Un poème pour la tulipe. Parfois farfelu, toujours le sien."
  }
]
